INSERT INTO public.training_lessons (id, module_id, title, description, lesson_type, content_body, sort_order, is_required, estimated_minutes, status, checklist_items, created_by)
VALUES
-- Module 1
('aa100000-0000-4000-8000-000000001011','aa100000-0000-4000-8000-000000000101','Trip Builder vs Itinerary Builder','Two tools, two jobs. Know which one you are in.','text',
'<h2>Two tools, two jobs</h2><table style="width:100%;border-collapse:collapse;font-size:0.92rem;"><tr style="background:#0D1B2A;color:#fff;"><th style="padding:10px;text-align:left;">Tool</th><th style="padding:10px;text-align:left;">What it manages</th><th style="padding:10px;text-align:left;">You go there to…</th></tr><tr><td style="padding:8px;"><strong>Trip Workspace / Trip Builder</strong></td><td style="padding:8px;">The trip <em>record</em>: client, dates, travelers, bookings, suppliers, pricing, payments, commissions</td><td style="padding:8px;">Add a booking, log a payment, check margin, change status</td></tr><tr><td style="padding:8px;"><strong>Itinerary Builder</strong></td><td style="padding:8px;">The trip <em>content</em>: day-by-day items, photos, descriptions, publishing</td><td style="padding:8px;">Build what the client sees and publish it</td></tr></table><h3>How to move between them</h3><ol><li>Open <strong>Trip Builder</strong> from the sidebar. You land on the <em>Trip Picker</em> — search or pick a recent trip.</li><li>Inside a trip, the <strong>breadcrumb bar</strong> at the top always shows where you are: Trips › [Trip Name] › Itinerary.</li><li>Use <strong>Switch view</strong> in the breadcrumb to jump between the trip record and the itinerary for the same trip — no back-button hunting.</li></ol><div style="padding:12px 14px;background:#f8f6f0;border-left:4px solid #C9A227;border-radius:6px;"><strong>Rule of thumb:</strong> money and records = Trip Builder. Words and pictures = Itinerary Builder.</div>',
1,true,10,'published','["Open Trip Builder and find a trip using search","Use Switch view to jump to that trip''s itinerary","Return to the trip record using the breadcrumb"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001012','aa100000-0000-4000-8000-000000000101','Building an Itinerary Day by Day','The full workflow from empty itinerary to publish-ready.','text',
'<h2>Workflow: empty itinerary → publish-ready</h2><ol><li><strong>Create the itinerary</strong> on the trip''s Itinerary tab. Set its own departure/return dates if they differ from the trip-level dates — itinerary dates win for display.</li><li><strong>Add days and items.</strong> Each item has a type (flight, hotel, activity, transfer, cruise, note), a time, a title, a location, and a description.</li><li><strong>Link items to bookings</strong> where one exists so pricing and confirmation numbers stay in sync.</li><li><strong>Add media</strong> — hero image, thumbnail, and additional photos (next lesson).</li><li><strong>Check the Pricing Summary</strong> panel. It rolls up item costs so you can sanity-check against the trip total before the client ever sees it.</li><li><strong>Preview</strong> using the client/portal preview, then <strong>Publish</strong>. Publishing writes a snapshot — later edits are not live until you publish again.</li></ol><h3>Common mistakes</h3><ul><li>Editing after publishing and assuming the client sees it. <strong>Re-publish.</strong></li><li>Leaving items with no time on a travel day — sequence looks random to the client.</li><li>Pass-through costs written into descriptions instead of margin lines.</li></ul>',
2,true,15,'published','["Create an itinerary and add at least 3 days of items","Link one item to an existing booking","Publish and view the client-facing result"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001013','aa100000-0000-4000-8000-000000000101','Photos & Multi-Image Galleries','Add a hero image plus a swipeable gallery to any itinerary item.','text',
'<h2>Images on itinerary items</h2><p>Every itinerary item has a <strong>Media</strong> tab in the item editor:</p><ul><li><strong>Main image</strong> — the hero photo shown on the item card.</li><li><strong>Thumbnail</strong> — small preview used in list views.</li><li><strong>Additional Photos</strong> — an ordered gallery. Upload several, drag to reorder, remove any.</li></ul><h3>Three ways to add an image</h3><ol><li>Click to browse and upload a file.</li><li>Drag and drop onto the upload field.</li><li><strong>Paste from clipboard</strong> — copy an image from a supplier page and paste directly.</li></ol><h3>Where the photos appear</h3><ul><li><strong>Agent itinerary builder</strong> — thumbnail with a photo-count badge (e.g. “+3”).</li><li><strong>Client portal &amp; admin preview</strong> — thumbnail plus a swipeable carousel inside each item.</li><li><strong>Published / shared trip page</strong> — full-bleed photo card with a gallery carousel underneath.</li></ul><div style="padding:12px 14px;background:#f8f6f0;border-left:4px solid #C9A227;border-radius:6px;"><strong>Standard:</strong> 3–5 photos on marquee items (ship, resort, headline excursion). One clean hero on everything else. Never upload screenshots with supplier pricing visible.</div>',
3,true,10,'published','["Add a main image and thumbnail to one item","Upload 3 additional photos and reorder them","Confirm the carousel renders in the portal preview"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001014','aa100000-0000-4000-8000-000000000101','The Shared Template Library','Stop rebuilding the same itinerary. Save it once, reuse it forever.','text',
'<h2>Templates: save once, reuse forever</h2><h3>Saving a template</h3><ol><li>Build an itinerary you are proud of.</li><li>Open the <strong>Templates</strong> action and choose <em>Save as template</em>.</li><li>Name it by what it actually is: “7-Night Western Caribbean — Family”, not “Template 3”.</li></ol><h3>Applying a template</h3><ol><li>On a trip''s itinerary, open <strong>Apply template</strong>.</li><li>Pick the template and confirm. Days and items are copied in, then <strong>dates are shifted</strong> to the target trip.</li><li>Edit the specifics: ship, hotel, confirmation numbers, pricing, photos.</li></ol><h3>Day-by-day template editor</h3><p>Templates have their own day-by-day editor so you can maintain the master copy directly — add days, reorder items, attach images — without touching a live client trip.</p><div style="padding:12px 14px;background:#fff4f4;border-left:4px solid #C0392B;border-radius:6px;"><strong>Watch out:</strong> if a template shows “no applyable items”, it was saved before content existed. Open it in the template editor and add days.</div><p>The email template library works the same way — shared across the agency, so approved language stays consistent.</p>',
4,true,10,'published','["Save one of your itineraries as a template","Apply a template to a new trip and verify dates shifted","Edit a template in the day-by-day editor"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

-- Module 2
('aa100000-0000-4000-8000-000000001021','aa100000-0000-4000-8000-000000000102','The Form Builder: Client Intake','Build questionnaires clients actually finish.','text',
'<h2>Form Builder (Marketing › Form Builder)</h2><p>Create intake questionnaires without waiting on anyone.</p><h3>Field types</h3><ul><li>Short text, long text, email, phone, number</li><li>Date, dropdown, multi-select, checkbox</li><li><strong>File upload</strong> — passports, marriage certificates, vaccination records</li></ul><h3>Workflow</h3><ol><li>Create a form, add fields, mark which are required.</li><li>Publish it — you get a public link at <code>/intake/&lt;slug&gt;</code>.</li><li>Send the link to the client (or embed it in an email template).</li><li>Responses land under <strong>Forms</strong> in the dashboard; uploads are stored securely and are only visible to the owning agent and admins.</li><li>Review the response and push mapped answers onto the client record.</li></ol><h3>Standards</h3><ul><li>Keep new-lead forms under 10 fields. Long forms get abandoned.</li><li>Ask for legal name exactly as printed on the passport.</li><li>Never ask for full card numbers on a form — use the credit card authorization flow.</li></ul>',
1,true,15,'published','["Build a 6-field intake form with one file upload","Submit a test response through the public link","Review the response in the Forms dashboard"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001022','aa100000-0000-4000-8000-000000000102','Passport Scanning (OCR)','Capture passport data in seconds instead of typing it.','text',
'<h2>Scan, do not type</h2><p>On a client profile (and on the client-facing document upload link) there is a <strong>Scan Passport</strong> button.</p><h3>Workflow</h3><ol><li>Click <strong>Scan Passport</strong> and upload a clear photo or PDF of the photo page.</li><li>The system reads the document and the machine-readable zone (MRZ).</li><li>Extracted fields are shown for review: full name, passport number, nationality, issuing country, sex, date of birth, issue date, expiry date.</li><li><strong>You verify every field</strong>, correct anything wrong, then save to the client record.</li></ol><h3>Quality rules</h3><ul><li>Flat, well-lit, whole page in frame, no glare across the MRZ.</li><li>Names must match the passport exactly — no nicknames, no dropped middle names.</li><li>Check expiry against the return date plus supplier/destination validity rules (often 6 months).</li></ul><div style="padding:12px 14px;background:#f8f6f0;border-left:4px solid #C9A227;border-radius:6px;">OCR is an accelerator, not an authority. A wrong passport number is a denied boarding. Always eyeball the result.</div>',
2,true,10,'published','["Scan a sample passport and review every extracted field","Correct one field and save to the client record","Flag a passport expiring within 6 months of return"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001023','aa100000-0000-4000-8000-000000000102','Parse Confirmation & Inbox Import','Turn supplier confirmation emails into booking records.','text',
'<h2>Parse Confirmation</h2><p>Open <strong>Parse Confirmation</strong> from a trip. Two tabs:</p><h3>1. Paste tab</h3><ol><li>Copy the raw supplier confirmation email.</li><li>Paste it in and run the parse.</li><li>The system extracts supplier, confirmation number, dates, travelers, and amounts.</li><li>Review, correct, then create or update the booking and itinerary item.</li></ol><h3>2. Inbox tab</h3><ol><li>Watched mailboxes pull supplier confirmations in automatically.</li><li>Pick the message from the Inbox list and import it directly — no copy/paste.</li><li>Duplicate detection warns you if that confirmation number already exists.</li><li>Link it to the correct existing booking rather than creating a second one.</li></ol><h3>Non-negotiables</h3><ul><li>Confirmation number must match the supplier document character for character.</li><li>Amounts go on <strong>margin lines</strong>, not into notes — the margin engine is the source of truth.</li><li>If the parse looks wrong, fix it in the review step. Never save a guess.</li></ul>',
3,true,15,'published','["Parse a pasted supplier confirmation and create a booking","Import one confirmation from the Inbox tab","Resolve a duplicate-confirmation warning by linking to the existing booking"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

-- Module 3
('aa100000-0000-4000-8000-000000001031','aa100000-0000-4000-8000-000000000103','Meet Donna: Your AI Assistant','What Donna can do, and where the guardrails are.','text',
'<h2>Donna</h2><p>Donna lives in her own chat launcher — separate from Team Chat so the two never get confused. Team channels are for people; Donna is for work.</p><h3>What Donna can do</h3><ul><li>Answer questions about your trips, clients, and bookings.</li><li>Draft client-facing copy and follow-up messages.</li><li><strong>Create a client from an approved lead proposal</strong> — she pulls the lead details across so you are not retyping them.</li></ul><h3>How to ask well</h3><ul><li>Name the trip or client. “Miles cruise” beats “that cruise”.</li><li>State the outcome you want, not just the topic.</li><li>Ask one thing at a time for anything that changes a record.</li></ul><h3>Guardrails</h3><ul><li>Donna only sees what <em>you</em> are allowed to see. Admins see more.</li><li>Anything Donna drafts is a draft. You own what goes to the client.</li><li>Never paste card numbers or passwords into any chat.</li></ul>',
1,true,10,'published','["Ask Donna to summarize one of your active trips","Use Donna to create a client from an approved lead proposal","Draft a client follow-up with Donna and edit before sending"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001032','aa100000-0000-4000-8000-000000000103','Nadia: AI Call Notetaker','Never lose what the client said on the call.','text',
'<h2>Nadia</h2><p>Nadia turns discovery and planning calls into structured notes attached to the client record.</p><h3>Workflow</h3><ol><li>After the call, add the recording or transcript to the client''s call notes.</li><li>Nadia produces a summary, key preferences, budget signals, and follow-up actions.</li><li>You review, fix anything misheard, and save.</li><li>The notes are then searchable from Notes Chat and visible on the client timeline.</li></ol><h3>Standards</h3><ul><li>Tell the client you are recording. Every time. No exceptions.</li><li>Log the call the same day — memory decays, deals decay with it.</li><li>Capture the <em>why</em> (anniversary, first cruise, mobility needs), not just the what.</li></ul>',
2,true,10,'published','["Log a call and generate notes with Nadia","Correct one detail in the generated summary","Confirm the note appears on the client timeline"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001033','aa100000-0000-4000-8000-000000000103','Notes Chat: Search Everything','Ask questions across clients, calls, trips, and messages.','text',
'<h2>Notes Chat (/notes-chat)</h2><p>One search box across your entire book of business: client records, call notes, trips, and portal messages.</p><h3>Good questions to ask it</h3><ul><li>“Which clients mentioned an anniversary in 2027?”</li><li>“Who asked about Alaska but never got a proposal?”</li><li>“What did we agree on the Smith cruise about cabin category?”</li></ul><h3>Scope</h3><p>Results are scoped to <strong>your</strong> records. Admins and office admins see agency-wide results. That scoping is enforced on the server — it is not a UI setting.</p><h3>Use it before you ask a human</h3><p>Most “what happened with…” questions are already answered somewhere in your notes. Search first, escalate second.</p>',
3,true,10,'published','["Run three different Notes Chat searches","Find a past client detail you had forgotten","Turn one search result into a follow-up task"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

-- Module 4
('aa100000-0000-4000-8000-000000001041','aa100000-0000-4000-8000-000000000104','The 3-Step Client Approval & Payment Flow','What the client actually sees, step by step.','text',
'<h2>The client sees three steps. Nothing more.</h2><ol><li><strong>Review</strong> — the published itinerary and the itemized price breakdown.</li><li><strong>Approve</strong> — an e-signature approval of the itinerary and budget. This is what unlocks payment.</li><li><strong>Pay</strong> — deposit, installment, or pay in full, from a single Pay Now surface.</li></ol><h3>Why clients used to get stuck</h3><ul><li>Payment options appeared before approval, so the order was unclear.</li><li>Duplicate payment records made balances look wrong.</li></ul><p>Both are fixed: the stepper shows exactly where the client is and what is next, and payment records are de-duplicated server-side.</p><h3>Pricing breakdown rules</h3><ul><li>Pricing is <strong>always</strong> broken down on the Pricing &amp; Payment tab — for every trip.</li><li>Pass-through costs are masked appropriately; the client sees what they are paying, itemized.</li></ul><h3>Your job</h3><ol><li>Publish the itinerary.</li><li>Confirm the price breakdown is complete and correct.</li><li>Send the portal link and tell the client plainly: review, approve, then pay.</li><li>Watch for the approval notification, then confirm the payment landed.</li></ol>',
1,true,15,'published','["Walk a test client through all three steps in the preview","Verify the price breakdown itemizes correctly","Confirm you receive the approval notification"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001042','aa100000-0000-4000-8000-000000000104','Credit Card Authorizations','How auths work, and the rule that trips people up.','text',
'<h2>Credit card authorizations</h2><div style="padding:12px 14px;background:#f8f6f0;border-left:4px solid #C9A227;border-radius:6px;"><strong>The rule:</strong> an authorization covers the <em>cost of the whole trip</em> unless it explicitly says otherwise.</div><h3>Workflow</h3><ol><li>Send the client the secure authorization form (never collect card data over chat, email, or phone notes).</li><li>The client submits; card data is stored encrypted.</li><li>To use it, open the booking and choose <strong>View CC Info</strong>. You must re-authenticate — card details are visible for a short window only.</li><li>Charge the supplier, then log the payment on the trip.</li></ol><h3>Lifecycle</h3><ul><li>Authorizations expire after 30 days.</li><li>An auth expires automatically once the trip is paid in full.</li><li>Every reveal is logged for compliance.</li></ul><h3>Never</h3><ul><li>Never screenshot card details.</li><li>Never store a card in a note, a form field, or a template.</li></ul>',
2,true,10,'published','["Send a test authorization link","Re-authenticate and view CC info on a booking","State the whole-trip auth rule from memory"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001043','aa100000-0000-4000-8000-000000000104','Client Self-Service Excursions','Let clients browse and request excursions themselves.','text',
'<h2>Excursions in the portal</h2><p>Clients can browse excursion inventory from their portal and submit requests instead of emailing you a wish list.</p><h3>Workflow</h3><ol><li>Client opens <strong>Excursions</strong> in the portal and browses options for their destination.</li><li>They submit a request with date, party size, and notes.</li><li>The request lands in your queue on the trip.</li><li>You confirm availability with the supplier, then create the booking and the itinerary item — with photos.</li><li>Cost goes on a margin line; commission follows automatically.</li></ol><h3>Positioning</h3><p>Excursions are the easiest margin on the trip and the highest-satisfaction add-on. Point every client at the tab during the approval step, not after they have paid in full.</p>',
3,true,10,'published','["Open the client excursions view and submit a test request","Convert a request into a booking and itinerary item","Confirm the margin line and commission calculated"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

-- Module 5
('aa100000-0000-4000-8000-000000001051','aa100000-0000-4000-8000-000000000105','Daily & Monthly Payment Reports','Know what came in, every single day.','text',
'<h2>/reports/daily-payments</h2><p>The report runs automatically <strong>twice a day (8am and 8pm ET)</strong> and reconciles incoming payments against trips.</p><h3>Two views</h3><ul><li><strong>Daily</strong> — every payment received, matched to a trip and client.</li><li><strong>By Month</strong> — month picker, KPI totals, and drill-down into any day.</li></ul><h3>How matching works</h3><ol><li>Match on client <strong>email + trip name</strong> first.</li><li>If there is no trip name, fall back to email only.</li><li>Anything unmatched shows up for manual review — clear it, do not ignore it.</li></ol><h3>Stripe fees</h3><p>Payments apply to the trip <strong>net of the Stripe fee</strong>. The actual fee is pulled from the transaction and stored on the payment, so the trip balance reflects real money received — not the gross charge.</p><h3>Daily habit</h3><p>Open the report each morning. Confirm yesterday''s payments matched. Resolve exceptions before they compound.</p>',
1,true,10,'published','["Review yesterday''s daily payment report","Switch to By Month and check the KPI totals","Resolve one unmatched payment"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001052','aa100000-0000-4000-8000-000000000105','Commission Splits, Mentors & Payouts','Multi-split commissions and how you get paid.','text',
'<h2>Commissions</h2><h3>Multi-split commissions</h3><ul><li>A booking''s commission can be split across multiple agents with explicit percentages.</li><li><strong>Mentor assignments</strong> route a share to the mentoring agent automatically.</li><li>Splits are edited on the booking; the statement reflects each line separately.</li></ul><h3>Statuses you will see</h3><ul><li><strong>Expected</strong> — booked, commission not yet received.</li><li><strong>Received</strong> — supplier paid; a received date is recorded.</li><li><strong>Paid out</strong> — confirmed on a payout run.</li></ul><h3>Workflow</h3><ol><li>Booking is confirmed → commission is calculated from margin lines.</li><li>Supplier pays → mark <strong>commission received</strong> with the date received.</li><li>Admin runs the payout, reviews the statement, and confirms payout.</li></ol><h3>Rules that matter</h3><ul><li><code>booking_margin_lines</code> is the absolute truth for money. Never override a total by hand in a note.</li><li>Overrides larger than the revenue trigger admin approval.</li><li>Holdbacks apply per policy and release on schedule.</li></ul>',
2,true,15,'published','["Add a two-way commission split on a test booking","Mark a commission received with its date","Read your statement and explain each line"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562'),

('aa100000-0000-4000-8000-000000001053','aa100000-0000-4000-8000-000000000105','Margin Compliance Quick Reference','The checks that keep the agency profitable and clean.','text',
'<h2>Before you mark a trip Booked</h2><ul><li>Every supplier cost has a <strong>margin line</strong> — no cost lives only in a note or an email.</li><li>Pass-through amounts are marked as pass-through, not as revenue.</li><li>Margin meets the minimum. A red warning means stop and fix, not proceed and explain later.</li><li>Confirmation numbers are entered exactly as issued.</li><li>Payment schedule and deadlines are on the trip so reminders fire.</li></ul><h3>When totals look wrong</h3><ol><li>Recalculate margin from the booking (the recalc runs server-side).</li><li>Wait for the recalculation and triggers to finish before judging the UI.</li><li>If it still disagrees, compare line items against the supplier invoice — the line items win.</li></ol><div style="padding:12px 14px;background:#fff4f4;border-left:4px solid #C0392B;border-radius:6px;"><strong>Never</strong> delete a booking or trip with payments or credit card authorizations attached. Deletion is blocked, and for good reason.</div>',
3,true,10,'published','["Run the margin checklist on one live trip","Recalculate margin and compare to the supplier invoice","Identify one pass-through cost and mark it correctly"]'::jsonb,'5c2d70a4-a902-47fa-aaf0-f29fc2eb1562')
ON CONFLICT (id) DO UPDATE SET module_id=EXCLUDED.module_id, title=EXCLUDED.title, description=EXCLUDED.description, content_body=EXCLUDED.content_body, sort_order=EXCLUDED.sort_order, status=EXCLUDED.status, estimated_minutes=EXCLUDED.estimated_minutes, checklist_items=EXCLUDED.checklist_items;
